#include "unity.h"
#include "app_config.h"
#include "alert_indicator.h"

void setUp(void)
{
}

void tearDown(void)
{
}

void test_FR_037_01(void)
{
    alert_indicator_state_t state;
    alert_indicator_init(&state);

    alert_indicator_output_t output =
        alert_indicator_update(&state, 1000U, MOTION_EVENT_SPEEDING);
    TEST_ASSERT_TRUE(output.event_is_active);
    TEST_ASSERT_EQUAL_INT((int)MOTION_EVENT_SPEEDING, (int)output.active_event);

    /* The event remains active, and the LED continues its cycle, before the 2 s limit. */
    output = alert_indicator_update(&state, 2000U, MOTION_EVENT_NONE);
    TEST_ASSERT_TRUE(output.event_is_active);
    TEST_ASSERT_EQUAL_INT((int)MOTION_EVENT_SPEEDING, (int)output.active_event);
    TEST_ASSERT_TRUE(output.led_is_on);

    output = alert_indicator_update(&state, 2500U, MOTION_EVENT_NONE);
    TEST_ASSERT_TRUE(output.event_is_active);
    TEST_ASSERT_FALSE(output.led_is_on);

    output = alert_indicator_update(&state, 2999U, MOTION_EVENT_NONE);
    TEST_ASSERT_TRUE(output.event_is_active);
    TEST_ASSERT_EQUAL_INT((int)MOTION_EVENT_SPEEDING, (int)output.active_event);

    /* At exactly 2 s after the last event, the code expires the active indication. */
    output = alert_indicator_update(&state, 3000U, MOTION_EVENT_NONE);
    TEST_ASSERT_FALSE(output.event_is_active);
    TEST_ASSERT_EQUAL_INT((int)MOTION_EVENT_NONE, (int)output.active_event);
    TEST_ASSERT_FALSE(output.led_is_on);
}
